// blankLine reports whether a row of the grid has nothing written in it.
func blankLine(line []string) bool {
	for _, value := range line {
		if strings.TrimSpace(value) != "" {
			return false
		}
	}
	return true
}

// concealedNamed writes what a sheet hid, for the warning that says so: rows,
// columns, or both, and nothing when nothing was hidden. The phrase ends in a
// count, and the particle that follows a count is always the same one, so it
// is written here rather than chosen in the warning for a phrase it cannot see.
func concealedNamed(rows, columns int) string {
	var parts []string
	if rows > 0 {
		parts = append(parts, fmt.Sprintf("행 %d개", rows))
	}
	if columns > 0 {
		parts = append(parts, fmt.Sprintf("열 %d개", columns))
	}
	if len(parts) == 0 {
		return ""
	}
	return strings.Join(parts, "와 ") + "는"
}

// sheetPart joins a workbook-relative part name, which may already be absolute.
func sheetPart(name string) string {
	if strings.HasPrefix(name, "xl/") {
		return name
	}
	return "xl/" + name
}

// gridOf reads a sheet into rows of text, in the cells' own positions: a sheet
// leaves out empty cells, and reading them in order would shift a row left.
//
// The position is in the cell's own reference where it has one. It is allowed
// not to have one — the reference is optional, and the writers that stream a
// sheet out row by row leave it off — and then the cell is simply the next one
// along. Reading a missing reference as column A instead put every cell of the
// row in the same place and kept the last: a two-column sheet came back as one
// column of figures with the labels gone, and the deck said nothing about it.
func gridOf(sheet worksheet, shared []string, formats cellFormats) [][]string {
	grid := make([][]string, 0, len(sheet.Rows))
	for _, row := range sheet.Rows {
		cells := map[int]string{}
		widest := -1
		next := 0
		for _, cell := range row.Cells {
			column := columnOf(cell.Reference)
			if column < 0 {
				column = next
			}
			next = column + 1
			value := cell.Value
			switch cell.Type {
			case "s":
				if index, err := strconv.Atoi(strings.TrimSpace(cell.Value)); err == nil && index >= 0 && index < len(shared) {
					value = shared[index]
				}
			case "inlineStr":
				value = cell.Inline
			case "b":
				// A logical cell stores TRUE as 1 and FALSE as 0, and the sheet
				// shows the word. Read as the number it stores, a checklist came
				// back as a column of 0s and 1s and was drawn as a bar chart of
				// them; with a format on the cell it was worse, because 1 under a
				// date format is a day and 0 under a per cent is "0%".
				value = truthOf(cell.Value)
			case "d":
				// A workbook written to the strict schema keeps a date as the
				// date, not as a count of days. It is the format that says how
				// much of it the sheet shows, the same as for a count.
				if shown, ok := formats.moment(cell.Style, value); ok {
					value = shown
				}
			case "str", "e":
				// A formula's cached result: text, or the error it ended in.
				// Neither is a number, so neither is a day or a per cent —
				// a formula that returned the characters "45678" into a
				// date-formatted cell is not 2025-01-21.
			default:
				// A number carries its meaning in its format: a day counted
				// from 1899-12-30, or a fraction of one written as a per cent.
				if shown, ok := formats.written(cell.Style, value); ok {
					value = shown
				}
			}
			cells[column] = strings.TrimSpace(value)
			if column > widest {
				widest = column
			}
		}
		line := make([]string, widest+1)
		for column, value := range cells {
			if column >= 0 && column <= widest {
				line[column] = value
			}
		}
		grid = append(grid, line)
	}
	return grid
}

// truthOf writes a logical cell the way a spreadsheet shows it. Anything that
// is neither of the two things a logical cell can store is left as it is.
func truthOf(value string) string {
	switch strings.TrimSpace(value) {
	case "1":
		return "TRUE"
	case "0":
		return "FALSE"
	}
	return value
}

// columnOf reads the column out of a cell reference such as "BC12", and
// returns -1 for a reference that names no column at all.
func columnOf(reference string) int {
	column := 0
	for _, symbol := range strings.ToUpper(strings.TrimSpace(reference)) {
		if symbol < 'A' || symbol > 'Z' {
			break
		}
		column = column*26 + int(symbol-'A') + 1
	}
	if column <= 0 {
		return -1
	}
	return column - 1
}
# Ptium architecture

Ptium is a single-tenant deployable, multi-user AI presentation workspace. The
runtime deliberately has one hard infrastructure dependency: PostgreSQL. The Go
API applies its own idempotent schema migrations and keeps service configuration,
identity mappings, decks, generated slides, API credentials and incidents in the
same database. An external queue, cache or object store can be added later, but is
not required to start or operate the baseline service.

```text
Browser / API client / MCP client
                |
        React single-page app
                |
       /api/v1 REST   /mcp JSON-RPC
                |
            Go service
       +--------+---------+
       |                  |
OIDC discovery/JWKS   AI provider adapter
       |                  |
   Keycloak       OpenAI-compatible endpoint
       \                  /
             PostgreSQL
      (settings, decks, slides, template packages)
```

## Runtime boundaries

- `web/` is a Vite/React/TypeScript SPA. It owns the presentation workspace and
  the separately gated administrator console.
- `server/` is a Go HTTP service. It owns authentication, authorization,
  generation, persistence, REST, MCP, key lifecycle and incident collection.
- `api/openapi.yaml` is the stable public REST contract. MCP is described in
  `docs/mcp.md`.
- `docker-compose.yml` is a local reference deployment, not a requirement. A
  compiled process can start with only `DATABASE_URL`.
- The release image is one static binary that also serves the compiled
  workspace, so a pod is a single container on a single port. No reverse proxy
  and no database are bundled; `deploy/kubernetes.yaml` is the reference
  manifest.

## Request lifecycle

Every API request receives a request ID. The authentication middleware accepts
either a verified OIDC access token or a hashed Ptium API key. The authorization
layer resolves ownership, role and key scope before the handler reaches storage.
Unexpected failures are returned as a stable JSON error and recorded as an
incident with a fingerprint, request ID, severity, redacted context and lifecycle
state. Administrators can acknowledge, resolve or reopen the incident without
access to secrets.

Presentation generation is persisted as an explicit state transition:

```text
draft -> queued -> generating -> ready
                         \-> failed -> queued (retry)
```

Generation is template-aware from end to end. Every deck is bound to a
PowerPoint template — one the customer uploaded or one of the designs Ptium
ships with — and the template's layout catalogue drives both writing and
export.

```text
upload .pptx/.potx
        |
   analyzer  ->  manifest: slide size, theme colours and fonts, per-layout
        |        placeholders with role, position and text capacity
        |
   plan pass  ->  narrative arc, one layout chosen per slide
        |
   write pass ->  copy written into named slots inside their budgets
        |
   composer  ->  validates slots, repairs unknown layouts, fits overflow
        |
   renderer  ->  original package + newly generated slide parts
```

If an administrator configured an OpenAI-compatible provider, the two passes run
against it. Otherwise Ptium uses its deterministic local generator, which builds
the same narrative arc and layout variety without a network call, so onboarding
and air-gapped deployments remain fully usable.

## The design system

A slide is not filled in, it is composed. `internal/pptx` resolves a design
system from the template itself — surface and ink tokens, a validated
categorical order, a type scale and an 8pt spacing rhythm — and lays each slide
component out against it.

A component is laid out once into primitives and emitted twice: as DrawingML for
the exported file and as SVG for the browser preview. That is the only way the
two can be guaranteed to agree, and it is why a preview is worth trusting.

Charts are drawn as native shapes rather than embedded chart parts, so a deck
carries no hidden workbook and cannot open with a repair prompt. The rules they
follow are the ones a designer would apply by hand: colour is assigned by the
job it does, marks stay thin, values are direct-labelled instead of gridded,
stacked segments are separated by a gap rather than a border, and a categorical
# Ptium v2 — 무엇을 먼저 만들 것인가

이 문서는 v0.44 시점의 코드를 기준으로, 다음 열 판에서 만들 것을 순서대로 적습니다. 아이디어
목록이 아니라 **착수 순서와 그 이유**입니다.

## 이미 있는 것 (다시 만들지 않을 것)

새 기능을 논의하기 전에, 이미 서 있는 것을 분명히 해 둡니다.

| 이미 있음 | 어디에 |
| --- | --- |
| 생성 잡 큐 (Postgres, `FOR UPDATE SKIP LOCKED`, 워커가 30초마다 살아 있다고 말하고, 3분 동안 조용하면 재확보) | `store.ClaimGeneration` · `generation/worker.go` |
| 브라우저 E2E (생성→편집→저장→내보내기 · 발표자 보기 · 키보드 · 좁은 화면) | `scripts/e2e/{ui,flows,deep}.py` |
| 내보낸 파일의 외부 검증 (python-pptx로 표·차트·워크북·번호·노트·대체 텍스트) | `scripts/e2e/package.py` |
| 슬라이드 라이브러리 (등록·검색·사용 횟수) | `store/snippets.go` · `SlideLibrary.tsx` |
| 측정 8종 (overflow · outside · collision · contrast · orphan · density · repeat · notes) + 안전 수정 | `pptx/inspect.go` · 편집기 측정 대화상자 |
| 기존 `.pptx` 가져오기 (글 · 표 · 그림 · **차트의 숫자**) | `pptx/importdeck.go` · `deck/importdeck.go` |
| 편집 가능한 표 · 차트 내보내기 (워크북 포함) | `pptx/tablepart.go` · `pptx/chartpart.go` |
| 모든 개체 대체 텍스트 (접근성 검사 통과) | `pptx/describe.go` |
| REST와 MCP가 같은 권한 계층 · API 키 회전 · OIDC | `httpapi` · `keys` · `auth` |

## 진짜 공백

| 공백 | 크기 |
| --- | --- |
| 품질을 **점수로** 말하지 않는다 (측정은 하는데 목록으로만 보여 준다) | 큼 |
| 숫자의 **출처**가 없다 | 큼 |
| 데이터에 **연결된** 슬라이드가 없다 | 큼 |
| 편집기에서 **말로 시키는** 통로가 없다 | 큼 |
| 라이브러리를 **먼저 찾아보고** 생성하지 않는다 | 중간 |
| `EditorPage.tsx` 81KB · 프론트 유닛 테스트 없음 | 중간 |
| 내보낸 파일의 **golden 비교**가 없다 | 중간 |
| 협업(공유 · 댓글 · 승인) | 중간 |

---

## 1차 — 프레젠테이션 품질 점수

**왜 먼저인가.** 측정 엔진이 이미 8종을 재고 있고, 편집기는 그것을 "다듬을 곳 2"로 보여 줍니다.
점수는 그 위에 얇게 얹히는 층이고, 사용자에게는 **"이 덱이 지금 몇 점인가"**라는 처음 보는
정보가 생깁니다. 새 모델도, 새 인프라도 필요 없습니다.

**정직하게.** 점수는 **그려진 것을 잰 결과**이지 논지의 설득력이 아닙니다. 화면에서도 그렇게
말합니다.

차원은 측정할 수 있는 것만 둡니다.

| 차원 | 무엇으로 계산하는가 |
| --- | --- |
| 가독성 | overflow · outside · density · orphan |
| 구성 | repeat · notes 없음 · 요점 수 |
| 시각 | collision · 빈 영역 · 컴포넌트 비율 |
| 접근성 | contrast · 대체 텍스트 · 제목 없는 슬라이드 |

API는 이미 있는 `GET /presentations/{id}/inspect` 를 넓힙니다.

```json
{
  "slides": 9, "defects": 0, "advisories": 2,
  "score": {
    "total": 92,
    "dimensions": [{"key":"readability","score":95,"counted":3}],
    "slides": [{"slide":3,"score":74,"worst":"density"}]
  },
  "findings": [...]
}
```

편집기 머리의 칩이 `품질 92` 가 되고, 눌러 연 대화상자가 차원 막대와 **가장 낮은 슬라이드**를
먼저 보여 줍니다.

## 2차 — 근거와 출처 *(v0.46에서 1단계 완료)*

기업 문서에서 AI가 쓴 숫자의 첫 질문은 언제나 "이거 어디서 나온 겁니까"입니다.

문장 단위로 답합니다.

**v0.46에서 한 것:** 소스 언어의 `!source`, 슬라이드에 함께 저장(문서와 같이 이동), 왕복 보존,
발표자 노트에 출처 목록, 측정 항목 `숫자의 출처 없음`, 점수의 **근거** 축.

**아직 남은 것:** 덱을 가로지르는 출처 검색과 재사용, 파일에서 가져온 근거의 자동 연결, 참고
슬라이드 생성. 그때 아래 표가 필요해집니다 — 지금은 슬라이드 문서 안에 사는 편이 낫습니다.

```sql
CREATE TABLE evidence (
  id uuid PRIMARY KEY,
  presentation_id uuid NOT NULL,
  slide_position int NOT NULL,
  claim text NOT NULL,          -- 슬라이드에 적힌 그 문장
  source_kind text NOT NULL,    -- upload | url | dataset | manual
  source_title text NOT NULL,
  source_locator text,          -- p.42, Sheet1!B7, #anchor
  retrieved_at timestamptz,
  confidence real
);
```

- 소스에서: `- 매출 1,240억 ^1` 처럼 각주를 답니다.
- 내보낼 때: 발표자 노트 끝에 출처 목록이 붙고, 원하면 **참고 슬라이드**가 마지막에 생깁니다.
- 측정에 한 줄 늘어납니다: **숫자가 있는데 출처가 없는 슬라이드**.

## 3차 — 문서에서 만들기 *(v0.47에서 1단계 완료: xlsx · csv · docx · md)*

`.pptx` 가져오기는 이미 있었고, v0.47에서 **xlsx · csv · tsv · docx · md · txt** 가 같은 자리에
붙었습니다 — 모두 표준 라이브러리만으로, 의존성 없이. 남은 것은 **PDF** 하나이고, 그것은 파서
의존성을 들일지 결정하는 문제입니다. 파일에서 뽑은 문단과 표가 **2차의 근거**로 그대로 이어집니다 — 이 순서가 중요합니다.
출처 없이 문서를 삼키면 AI가 지어낸 것과 구분되지 않습니다.

## 4차 — 편집기 코파일럿 *(v0.48에서 1단계 완료: 결정적 명령)*

말로 시키는 통로. 핵심은 채팅이 아니라 **편집 명령으로의 번역**입니다.

```
자연어 → 의도 → 편집 명령 → 덱 변경 → 측정 → 되돌릴 수 있는 한 판
```

**v0.48에서 한 것:** 합치기 · 나누기 · 옮기기 · 복제 · 삭제 · 줄이기(장수/발표 시간)를 문장에서
읽어 실행합니다. 모델 없이, 한국어와 영어 모두. 적용 전에 계획을 보여 주고, 버전 이력으로
되돌립니다.

